// 자동 생성 파일 — 직접 고치지 말 것. `node scripts/build-land-mask.mjs` 로 다시 굽는다.
// 출처: world-atlas/land-50m.json (Natural Earth, public domain)
// 1024×512 1비트 equirectangular 육지 마스크. 비트 순서는 LSB first, 행 우선.
// 행 0 = 북위 90°, 열 0 = 서경 180°.

export const LAND_MASK_WIDTH = 1024;
export const LAND_MASK_HEIGHT = 512;

/** base64(1비트 패킹). 런타임에서 `atob` 한 번으로 푼다. */
export const LAND_MASK_BASE64 =
  "";
